/* public/js/35-lizards.js -- yellow-spotted lizards. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- yellow-spotted lizards ---------- */
/* PERF: a lizard used to be 20 separate meshes (body, head, tail, 11 spots, 2 eyes, 4 legs), and there are 48 of
   them, so lizards alone cost ~1,000 draw calls a frame (plus the shadow pass). Now each lizard is 2 meshes:
   the body with everything that doesn't move baked in, and the tail (kept separate because it wags).
   Both geometries are built once and shared by every lizard. */
const LIZ_BODY=mergeBoxes([
  [0.36,0.16,0.9,0x6f7a3a,0,0.1,0],[0.28,0.14,0.3,0x6f7a3a,0,0.12,0.56],   // body, head
  ...Array.from({length:11},(_,i)=>[0.07,0.02,0.07,0xf2d52a,(i%3-1)*0.11,0.19,-0.35+i*0.08]),   // yellow spots
  [0.05,0.05,0.05,0xd11a1a,-0.12,0.18,0.64],[0.05,0.05,0.05,0xd11a1a,0.12,0.18,0.64],          // red eyes
  ...[[-1,0.3],[1,0.3],[-1,-0.3],[1,-0.3]].map(([lx,lz])=>[0.1,0.06,0.18,0x5a6330,lx*0.23,0.03,lz]),   // legs
]);
const LIZ_TAIL=mergeBoxes([[0.14,0.1,0.8,0x626c33,0,0,-0.4]]);
const LIZARD_DRAW_R=130;   // PERF: lizards farther than this from the camera are hidden (they're lost in the haze anyway)
function makeLizard(){
  const g=new T.Group();
  const body=new T.Mesh(LIZ_BODY,mergedMat);body.castShadow=true;body.receiveShadow=true;g.add(body);
  const tail=new T.Mesh(LIZ_TAIL,mergedMat);tail.castShadow=true;tail.position.set(0,0.1,-0.45);g.add(tail);
  return{g,tail};
}
const lizards=[];
{const homes=preHoles.filter(h=>Math.hypot(h.x,h.z-20)>45).sort(()=>rng()-0.5).slice(0,48);
 homes.forEach((h,i)=>{const m=makeLizard();scene.add(m.g);lizards.push({home:h,m,x:h.x,z:h.z,ph:i*1.7,w:0.08+rng()*0.06,mode:'wander',hissT:0,yaw:0})})}

